/**
 * Generated from `docs/api/openapi.yaml` by `npm run okf:bundle`. Do not edit here.
 *
 * Bundled rather than read from disk because a serverless function is packed by
 * esbuild, which traces imports and cannot see a runtime `readFileSync`. On
 * Vercel the file simply would not be there, and `/api/openapi.json` would
 * throw ENOENT — a failure that only appears in production.
 */
export const OPENAPI_YAML = "openapi: 3.0.3\n\ninfo:\n  title: E2 API\n  version: 0.3.0\n  description: |\n    The read and control surface over the event spine.\n\n    **The one idea to hold on to:** there is a single append-only `events` table, and\n    every number this API returns is a *fold* over it. Replay, the A/B scoreboard, the\n    ROI report and the copilot all read the same log through the same predicates, which\n    is why they cannot disagree with each other. There is no separate analytics pipeline\n    to fall out of sync, and nothing here is precomputed.\n\n    A second idea that explains several response shapes: the log records **observable\n    facts only**. There is deliberately no `Converted` event, because \"converted\" means\n    different things to marketing, to sales and to finance. Each tenant declares its own\n    named metrics as predicates over the facts (`metrics:` in the journey spec), so\n    responses report metric *names the tenant chose* rather than a fixed vocabulary.\n\n    Money is always an **integer in minor units** — paise for INR, cents for USD. Never a\n    float, anywhere.\n  contact:\n    name: Platform team\n    email: fde@engati.com\n  license:\n    name: Proprietary\n\nservers:\n  - url: http://localhost:3000\n    description: Local development\n  - url: https://api.e2.example.com\n    description: Production\n\nsecurity:\n  - bearerAuth: []\n\ntags:\n  - name: Journeys\n    description: The declarative journey specifications and their versions.\n  - name: Replay\n    description: Counterfactual replay of historical leads through a different version.\n  - name: Simulation\n    description: Synthetic cohorts against a version, before any real lead is touched.\n  - name: Chat\n    description: Live conversations between a person and a published agent.\n  - name: Intelligence\n    description: ROI attribution, findings, and the copilot.\n  - name: Operations\n    description: Health and API discovery.\n\npaths:\n  /health:\n    get:\n      operationId: getHealth\n      tags: [Operations]\n      summary: Liveness probe\n      description: |\n        Answers without authentication so a load balancer can probe it. It reports that\n        the process is up; it does not check the database.\n      security: []\n      responses:\n        \"200\":\n          description: The process is running.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/HealthStatus\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/health:\n    get:\n      operationId: getHealthViaApi\n      tags: [Operations]\n      summary: Liveness probe, under the API prefix\n      description: |\n        Identical to `/health`. Both exist because a host that routes everything under\n        `/api` to a single function cannot reach a path outside that prefix, and a load\n        balancer conventionally probes the bare one.\n      security: []\n      responses:\n        \"200\":\n          description: The process is running.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/HealthStatus\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/openapi.json:\n    get:\n      operationId: getOpenApiDocument\n      tags: [Operations]\n      summary: This document\n      description: |\n        The API surface as JSON, unauthenticated so a client can discover it before it\n        has a credential. A test asserts that every route the server registers appears\n        here and vice versa, so this document cannot drift away from the running code.\n      security: []\n      responses:\n        \"200\":\n          description: The OpenAPI 3.0 document.\n          content:\n            application/json:\n              schema:\n                type: object\n                description: An OpenAPI 3.0 document.\n                additionalProperties: true\n                example: { openapi: \"3.0.3\" }\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/openapi.yaml:\n    get:\n      operationId: getOpenApiDocumentAsYaml\n      tags: [Operations]\n      summary: This document, as YAML\n      description: |\n        Byte-for-byte the authored source of this specification. The JSON form is parsed\n        from it, so the two cannot disagree.\n      security: []\n      responses:\n        \"200\":\n          description: The OpenAPI 3.0 document as YAML.\n          content:\n            application/yaml:\n              schema:\n                type: string\n                description: An OpenAPI 3.0 document in YAML.\n                example: \"openapi: 3.0.3\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/versions:\n    get:\n      operationId: listJourneyVersions\n      tags: [Journeys]\n      summary: List the published versions of a journey\n      description: |\n        Newest first. Versions are immutable once published: a change is always a new\n        version, which is what lets lift be attributed to a specific edit.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n      responses:\n        \"200\":\n          description: The published version numbers, newest first.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/JourneyVersionList\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/diff:\n    get:\n      operationId: diffJourneyVersions\n      tags: [Journeys]\n      summary: Structural diff between two versions\n      description: |\n        A characterisable, path-level diff — `evidence.decision_maker.required` went from\n        `false` to `true`. This is what makes an A/B result actionable: you can attribute\n        lift to a named change. A journey written as a prose prompt cannot be diffed this\n        way, which is the concrete reason this platform declares journeys instead.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/VersionA\"\n        - $ref: \"#/components/parameters/VersionB\"\n      responses:\n        \"200\":\n          description: Every path that differs between the two versions.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/SpecDiff\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/live:\n    get:\n      operationId: getLiveVersion\n      tags: [Journeys]\n      summary: Which version answers by default\n      description: |\n        Distinct from the newest published version, and that distinction is the point:\n        publishing makes a version exist so it can be tried, promoting makes it the one\n        real traffic meets. A chat session with no version named gets this one.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n      responses:\n        \"200\":\n          description: The live version.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/LiveVersion\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/promote:\n    post:\n      operationId: promoteJourneyVersion\n      tags: [Journeys]\n      summary: Point default traffic at a published version\n      description: |\n        Shipping, as a separate act from publishing. The version must already be\n        published; this only moves the pointer, so it is instant and reversible — promote\n        the previous version back and traffic returns to it on the next session.\n\n        Sessions already in flight keep the version they started on. A conversation whose\n        agent changed mid-way would be neither version's result.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/PromoteRequest\"\n      responses:\n        \"200\":\n          description: Promoted. New sessions get this version.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/LiveVersion\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/source:\n    get:\n      operationId: getJourneySource\n      tags: [Journeys]\n      summary: The authored YAML for a version\n      description: |\n        Byte for byte as it was published. Key order in the source is load-bearing —\n        routing is first-match-wins, and a spec round-tripped through JSON comes back with\n        its rules reordered — so the editor loads this rather than a re-serialised spec.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/JourneyVersion\"\n      responses:\n        \"200\":\n          description: The version and its source.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/JourneySource\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/lint:\n    post:\n      operationId: lintDraftJourney\n      tags: [Journeys]\n      summary: Check YAML that has not been published yet\n      description: |\n        The editor's companion: it checks a draft while someone is still typing, so a\n        problem surfaces before publishing rather than after.\n\n        **YAML that does not parse returns 200 with `valid: false`**, not an error status.\n        A malformed draft is an expected state of an editor, and the caller needs the\n        message to display, not a failed request.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/DraftSpec\"\n      responses:\n        \"200\":\n          description: Whether it parses, and every warning against it.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/DraftLintResult\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/publish:\n    post:\n      operationId: publishJourneyVersion\n      tags: [Journeys]\n      summary: Publish a new journey version\n      description: |\n        **Publishing is deployment.** There is no separate deploy step: from the moment\n        this returns, a new chat session can be served by this version, and a traffic\n        split can send it real leads.\n\n        Versions are immutable. Republishing a version number that exists returns 409 —\n        bump the version instead. That immutability is what makes lift attributable to a\n        named change rather than to \"the prompt at some point last month\".\n\n        Lint warnings are returned with the published version rather than blocking it: a\n        spec may legitimately rely on optional evidence a lead volunteers, and the platform\n        should not be the judge of that.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/DraftSpec\"\n      responses:\n        \"200\":\n          description: Published, and live for new conversations.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/LintReport\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"409\":\n          description: That version number is already published, and versions are immutable.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Error\"\n              example:\n                error: mba-admissions-qualification v5 is already published; versions are immutable\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/lint:\n    get:\n      operationId: lintJourneyVersion\n      tags: [Journeys]\n      summary: Static checks against a journey version\n      description: |\n        Catches journeys that cannot do what they claim, before a single lead meets them.\n\n        The check that motivated this endpoint: a journey whose *required* evidence can\n        never reach its own qualifying threshold will qualify nobody, and the symptom —\n        a simulation run reporting 0% qualified — looks like broken software rather than\n        a broken spec. It also flags scoring weights on fields that do not exist, metrics\n        that do not parse, and a booking metric in a journey whose routing never hands off.\n\n        These are warnings, not errors: a spec may legitimately rely on optional evidence\n        a lead volunteers. Omit `version` for the latest.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/JourneyVersion\"\n      responses:\n        \"200\":\n          description: The version checked, and every warning against it.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/LintReport\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/replay-estimate:\n    get:\n      operationId: estimateReplayCost\n      tags: [Replay]\n      summary: What a replay would cost, before committing to it\n      description: |\n        Opening a replay screen used to fire the full job on mount — thousands of leads,\n        hundreds of model calls, real money, no warning. Nothing that can spend should\n        start without someone choosing to, so this answers the question first.\n\n        Only leads whose evidence is **not already on the record** cost anything. A lead\n        the journey has already run carries its `EvidenceExtracted` events, and re-deriving\n        them from the same transcript would pay a model call to reproduce a recorded fact.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/VersionA\"\n        - $ref: \"#/components/parameters/VersionB\"\n        - $ref: \"#/components/parameters/CohortSize\"\n      responses:\n        \"200\":\n          description: How many leads, how many need extraction, and what that costs.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/ReplayEstimate\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/replay:\n    post:\n      operationId: replayCohort\n      tags: [Replay]\n      summary: Replay historical leads through a different journey version\n      description: |\n        Takes leads that already happened and asks what a different version would have\n        done with them. Returns the qualification lift with a 95% confidence interval and\n        the conversations where the two versions diverged.\n\n        **Read the two number families separately.** `observedConversionByDecision` is\n        measured from history and is a fact. `projectedConversions` applies those observed\n        rates to counterfactual routing and is a model. Presenting them as one number is\n        the fastest way to lose a room, so the API keeps them in separate fields and the\n        console renders them in different colours.\n\n        Omit `leadIds` to replay every lead on the journey.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/ReplayRequest\"\n      responses:\n        \"200\":\n          description: The lift, its interval, and the divergent conversations.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Lift\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/limits:\n    get:\n      operationId: getLimits\n      tags: [Operations]\n      summary: What this deployment will accept\n      description: |\n        A limit the client cannot see is a limit the client will exceed. Cohort sizes\n        differ by host — a serverless function has a wall-clock ceiling that a long-lived\n        server does not — so the console reads the ceiling rather than hardcoding a size\n        the host will then kill mid-run.\n      responses:\n        \"200\":\n          description: The deployment's operating limits.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Limits\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/simulate:\n    post:\n      operationId: simulateCohort\n      tags: [Simulation]\n      summary: Run a synthetic cohort against a journey version\n      description: |\n        Generates `n` personas, runs each through the version end to end, and scores the\n        conversations. Everything it writes is `sim`-scoped and carries a `runId`, so no\n        live-scoped read can ever see it.\n\n        This is how a new version is checked before a real lead meets it. Alerts fire on\n        declared thresholds — a policy breach or an evidence-collection drop — so a bad\n        version is caught here rather than in production.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/SimulateRequest\"\n      responses:\n        \"200\":\n          description: Run summary, aggregate quality, and any alerts that fired.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/SimulationResult\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/compare:\n    post:\n      operationId: compareJourneyVersions\n      tags: [Simulation]\n      summary: A/B two journey versions over one simulated cohort\n      description: |\n        Runs both versions against the **same seeded personas**, which is what makes the\n        comparison paired and the confidence interval honest. An unpaired interval over\n        two independently drawn cohorts would overstate the uncertainty and hide real\n        differences.\n\n        `verdict` is `inconclusive` whenever the interval spans zero. That is a result,\n        not a failure: it means the data does not support a decision yet.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/CompareRequest\"\n      responses:\n        \"200\":\n          description: Both arms, the deltas, and the verdict.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/Scoreboard\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/roi:\n    get:\n      operationId: getAttributionReport\n      tags: [Intelligence]\n      summary: Cost and outcomes attributed campaign to creative to journey version\n      description: |\n        A fold over the event log producing spend, outcome counts and cost per outcome at\n        each level of the hierarchy.\n\n        Two things to know before quoting a number from this endpoint:\n\n        1. **Each lead is evaluated under the metric definitions of the version it ran\n           under**, not the latest spec. Otherwise editing `conversion:` would silently\n           rewrite last quarter. When definitions drifted across versions present in the\n           data, `caveats` says the column sums two different questions.\n        2. **Media spend is allocated, not observed.** Ad platforms report per campaign\n           per day; the spine needs a lead on every event. Allocation is even, the method\n           travels in each `CostObserved` payload, and `caveats` states it. Model spend,\n           by contrast, is metered from real token usage.\n\n        `costPer` is `null` rather than infinity when nothing converted — an undefined\n        ratio, not an enormous one.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/ReportingCurrency\"\n      responses:\n        \"200\":\n          description: Totals, the attribution tree, and the assumptions behind them.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/AttributionReport\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/journeys/{journey}/insights:\n    get:\n      operationId: listInsights\n      tags: [Intelligence]\n      summary: Ranked findings about a journey\n      description: |\n        Seven detectors run over the folded log: evidence bottleneck, segment divergence,\n        drop-off, routing miscalibration, timing, policy friction and version regression.\n\n        Every finding carries its support (`n`), and every comparison carries a 95%\n        confidence interval. **A finding whose interval spans zero is not emitted**, and\n        neither is one below thirty leads on either side — noise shown to a marketer costs\n        the credibility the real findings then need. The one exception is routing\n        miscalibration, where \"hot and cold are indistinguishable\" *is* the finding.\n\n        `skipped` names the detectors that could not run and why. A detector that silently\n        returns nothing reads as a clean bill of health, which is the opposite of the\n        truth when the reason is that no policy event exists yet.\n      parameters:\n        - $ref: \"#/components/parameters/JourneyName\"\n        - $ref: \"#/components/parameters/ConversionMetric\"\n        - $ref: \"#/components/parameters/QualifiedMetric\"\n      responses:\n        \"200\":\n          description: Findings ranked by severity then effect size.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/InsightReport\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/chat/sessions:\n    post:\n      operationId: startChatSession\n      tags: [Chat]\n      summary: Begin a conversation with a published agent\n      description: |\n        A session is a lead. Everything it writes is `live`-scoped with no `runId`, so the\n        conversation lands in the same log the ROI and insight screens already read — a\n        real conversation is not a special case here, it is the ordinary case.\n\n        The first agent turn is **pinned and deterministic**, never a model call, so the\n        AI disclosure a person sees first cannot be improvised.\n\n        Pass `version` to talk to a specific one. Pass `split` instead — `{\"4\": 50, \"5\":\n        50}` — and the traffic allocator assigns deterministically, which is how a new\n        agent takes real traffic without disturbing the one already running. Pass neither\n        and the latest published version answers.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/StartChatRequest\"\n      responses:\n        \"200\":\n          description: The opening turn and the conversation's state.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/ChatReply\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/chat/sessions/{leadId}/messages:\n    post:\n      operationId: sendChatMessage\n      tags: [Chat]\n      summary: Say something, and get the agent's reply\n      description: |\n        One runtime step, persisted. Evidence extracted this turn, any score and route it\n        produced, and the tokens it cost are all written before this returns — cost per\n        turn rather than per conversation, because a conversation someone abandons still\n        cost real money and still belongs in cost per outcome.\n\n        `reply` is null when the agent has nothing left to say: the conversation completed,\n        or a policy rule escalated it to a human.\n      parameters:\n        - $ref: \"#/components/parameters/LeadId\"\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/ChatMessageRequest\"\n      responses:\n        \"200\":\n          description: The agent's reply and the updated state.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/ChatReply\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/chat/sessions/{leadId}:\n    get:\n      operationId: getChatSession\n      tags: [Chat]\n      summary: The full state of a conversation\n      description: |\n        Folded from the event log rather than held in memory, so a session survives a\n        restart and two clients watching the same conversation cannot disagree.\n      parameters:\n        - $ref: \"#/components/parameters/LeadId\"\n      responses:\n        \"200\":\n          description: The conversation and everything derived from it.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/ChatState\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\n  /api/copilot/ask:\n    post:\n      operationId: askCopilot\n      tags: [Intelligence]\n      summary: Ask a question about a journey, in words\n      description: |\n        The copilot reads through the same folds these endpoints expose — never raw SQL,\n        which from a model is both an injection surface and a hallucination surface. It\n        therefore cannot report a number the ROI endpoint disagrees with.\n\n        It may return a `view` (a rendering descriptor from a closed set: bar, table or\n        stat — never markup, so there is nothing to sanitise) and a `diff` (a proposed new\n        journey version).\n\n        **A returned `diff` has already been parsed, linted and diffed against the current\n        version.** An invalid proposal is handed back to the model to correct and never\n        reaches this response, so anything you receive here would publish as it stands.\n        Nothing is published by this endpoint.\n\n        When no model credential is configured the copilot answers by routing keywords to\n        the same tools and sets `offline: true`. The data is real either way; the\n        reasoning is not.\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/CopilotRequest\"\n      responses:\n        \"200\":\n          description: The answer, with an optional rendering and an optional proposal.\n          content:\n            application/json:\n              schema:\n                $ref: \"#/components/schemas/CopilotAnswer\"\n        \"400\":\n          $ref: \"#/components/responses/BadRequest\"\n        \"401\":\n          $ref: \"#/components/responses/Unauthorized\"\n        \"404\":\n          $ref: \"#/components/responses/NotFound\"\n        \"500\":\n          $ref: \"#/components/responses/InternalError\"\n\ncomponents:\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\n      description: |\n        Set `API_TOKEN` on the server to require it. Unset — the default for local\n        development — the guard is not installed and every endpoint is open. The hook is\n        real code either way, so enabling authentication is a variable, not a project.\n\n  parameters:\n    JourneyName:\n      name: journey\n      in: path\n      required: true\n      description: The journey's stable name, as declared by `journey:` in its spec.\n      schema:\n        type: string\n        minLength: 1\n        maxLength: 120\n        pattern: \"^[a-z0-9][a-z0-9-]*$\"\n        example: mba-admissions-qualification\n\n    VersionA:\n      name: a\n      in: query\n      required: true\n      description: The baseline version — the one currently live.\n      schema:\n        type: integer\n        minimum: 1\n        example: 3\n\n    VersionB:\n      name: b\n      in: query\n      required: true\n      description: The candidate version being evaluated against the baseline.\n      schema:\n        type: integer\n        minimum: 1\n        example: 4\n\n    JourneyVersion:\n      name: version\n      in: query\n      required: false\n      description: Which version to check. Omit for the latest published version.\n      schema:\n        type: integer\n        minimum: 1\n        example: 4\n\n    LeadId:\n      name: leadId\n      in: path\n      required: true\n      description: |\n        The session's lead id, returned when the session started. Chat leads carry a\n        `web_` prefix so a seed script's cleanup can never delete a real conversation.\n      schema:\n        type: string\n        pattern: \"^web_[0-9a-f]{16}$\"\n        example: web_3f9a21c07b4e6d15\n\n    CohortSize:\n      name: n\n      in: query\n      required: false\n      description: Cap the cohort to the first N leads. Omit for all of them.\n      schema:\n        type: integer\n        minimum: 1\n        example: 200\n\n    ReportingCurrency:\n      name: currency\n      in: query\n      required: false\n      description: |\n        ISO 4217 code for the reporting currency. Amounts are integer minor units of it.\n        Defaults to INR.\n      schema:\n        type: string\n        pattern: \"^[A-Z]{3}$\"\n        default: INR\n        example: INR\n\n    ConversionMetric:\n      name: conversion\n      in: query\n      required: false\n      description: |\n        Which of the tenant's declared metrics means \"converted\" for this question. There\n        is no platform-wide definition. If the named metric is not declared on the\n        journey, every detector is skipped with that reason rather than substituting a\n        guess.\n      schema:\n        type: string\n        minLength: 1\n        maxLength: 60\n        default: conversion\n        example: conversion\n\n    QualifiedMetric:\n      name: qualified\n      in: query\n      required: false\n      description: Which declared metric means \"qualified\".\n      schema:\n        type: string\n        minLength: 1\n        maxLength: 60\n        default: qualified_lead\n        example: qualified_lead\n\n  responses:\n    BadRequest:\n      description: The request was malformed or violated a stated constraint.\n      content:\n        application/json:\n          schema:\n            $ref: \"#/components/schemas/Error\"\n          example:\n            error: journey (string), a and b (integers) are required\n    Unauthorized:\n      description: The Bearer token was missing or invalid.\n      content:\n        application/json:\n          schema:\n            $ref: \"#/components/schemas/Error\"\n          example:\n            error: a valid Bearer token is required\n    NotFound:\n      description: |\n        The journey or version does not exist. Distinguished deliberately from a 502:\n        collapsing both into 404 once hid an authentication failure behind\n        \"journey not found\" for an afternoon.\n      content:\n        application/json:\n          schema:\n            $ref: \"#/components/schemas/Error\"\n          example:\n            error: \"journey not found: mba-admissions-qualification v9\"\n    InternalError:\n      description: |\n        An upstream dependency failed — the database, or the model provider. Returned as\n        502 by the running server when the failure is identifiably upstream.\n      content:\n        application/json:\n          schema:\n            $ref: \"#/components/schemas/Error\"\n          example:\n            error: connection refused\n\n  schemas:\n    Error:\n      type: object\n      description: The single error shape every endpoint uses on every failure.\n      required: [error]\n      additionalProperties: false\n      properties:\n        error:\n          type: string\n          description: A message written for the developer reading it, not an error code.\n          minLength: 1\n          maxLength: 500\n          example: currency must be a three-letter ISO code\n      example:\n        error: currency must be a three-letter ISO code\n\n    HealthStatus:\n      type: object\n      required: [ok]\n      additionalProperties: false\n      properties:\n        ok:\n          type: boolean\n          description: Always true when the process can answer at all.\n          example: true\n      example:\n        ok: true\n\n    JourneyVersionList:\n      type: object\n      required: [versions]\n      additionalProperties: false\n      properties:\n        versions:\n          type: array\n          description: Published version numbers, newest first.\n          items:\n            type: integer\n            minimum: 1\n            example: 4\n          example: [5, 4, 3]\n      example:\n        versions: [5, 4, 3]\n\n    SpecChange:\n      type: object\n      description: One path that differs between two versions.\n      required: [path, kind]\n      additionalProperties: false\n      properties:\n        path:\n          type: string\n          description: Dotted path into the parsed spec.\n          example: evidence.decision_maker.required\n        kind:\n          type: string\n          enum: [added, removed, changed]\n          example: changed\n        before:\n          nullable: true\n          description: The value in the earlier version. Absent when the path was added.\n          example: false\n        after:\n          nullable: true\n          description: The value in the later version. Absent when the path was removed.\n          example: true\n      example:\n        path: evidence.decision_maker.required\n        kind: changed\n        before: false\n        after: true\n\n    SpecDiff:\n      type: object\n      required: [changes]\n      additionalProperties: false\n      properties:\n        changes:\n          type: array\n          items:\n            $ref: \"#/components/schemas/SpecChange\"\n      example:\n        changes:\n          - path: version\n            kind: changed\n            before: 4\n            after: 5\n          - path: evidence.decision_maker.required\n            kind: changed\n            before: false\n            after: true\n\n    StartChatRequest:\n      type: object\n      required: [journey]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          minLength: 1\n          maxLength: 120\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          description: A specific version. Omit for the latest, or supply `split`.\n          example: 5\n        split:\n          type: object\n          description: |\n            Live A/B. Version number to percentage, summing to 100. Assignment is\n            deterministic, so re-running an experiment does not reshuffle anyone.\n          additionalProperties:\n            type: number\n            minimum: 0\n            maximum: 100\n          minProperties: 2\n          example: { \"4\": 50, \"5\": 50 }\n        source:\n          type: string\n          maxLength: 60\n          default: web_chat\n          example: web_chat\n        campaignId:\n          type: string\n          maxLength: 120\n          default: direct\n          example: meta_scholarships\n        creativeId:\n          type: string\n          maxLength: 120\n          default: console\n          example: cr_fees\n      example:\n        journey: mba-admissions-qualification\n        split: { \"4\": 50, \"5\": 50 }\n\n    ChatMessageRequest:\n      type: object\n      required: [text]\n      additionalProperties: false\n      properties:\n        text:\n          type: string\n          minLength: 1\n          maxLength: 2000\n          example: I am looking at the executive MBA for this intake.\n      example:\n        text: I am looking at the executive MBA for this intake.\n\n    ChatTurn:\n      type: object\n      required: [role, text, at]\n      additionalProperties: false\n      properties:\n        role:\n          type: string\n          enum: [agent, lead]\n          example: agent\n        text:\n          type: string\n          example: Hi, I am an AI assistant from the admissions team.\n        at:\n          type: string\n          format: date-time\n          example: \"2026-09-05T09:14:02.117Z\"\n\n    EvidenceView:\n      type: object\n      description: |\n        One field of the journey's declared evidence contract, and whether this\n        conversation has established it yet. Watching these fill in is the difference\n        between a declared contract and a prompt.\n      required: [field, required, value, confidence, sensitive]\n      additionalProperties: false\n      properties:\n        field:\n          type: string\n          example: budget_band\n        required:\n          type: boolean\n          example: true\n        value:\n          nullable: true\n          description: Null until established.\n          example: needs_financing\n        confidence:\n          type: number\n          format: double\n          nullable: true\n          minimum: 0\n          maximum: 1\n          example: 0.88\n        sensitive:\n          type: boolean\n          description: Declared `sensitive`, so the agent will not open with it.\n          example: true\n\n    ChatState:\n      type: object\n      required:\n        [leadId, journey, version, turns, evidence, missingRequired, score, decision, metrics, completed, escalated, escalationRule, modelCost, currency, offline]\n      additionalProperties: false\n      properties:\n        leadId:\n          type: string\n          example: web_3f9a21c07b4e6d15\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          example: 5\n        turns:\n          type: array\n          items:\n            $ref: \"#/components/schemas/ChatTurn\"\n        evidence:\n          type: array\n          items:\n            $ref: \"#/components/schemas/EvidenceView\"\n        missingRequired:\n          type: array\n          description: Required fields still to be established. Empty means ready to score.\n          items:\n            type: string\n            example: budget_band\n          example: [budget_band]\n        score:\n          type: integer\n          nullable: true\n          minimum: 0\n          maximum: 100\n          description: Null until required evidence is complete.\n          example: 80\n        decision:\n          type: string\n          nullable: true\n          description: The routing decision, named by the journey's own routing block.\n          example: hot\n        metrics:\n          type: object\n          description: |\n            The journey's OWN declared metrics, evaluated live over this conversation.\n            There is no platform-wide notion of \"qualified\" to report instead.\n          additionalProperties:\n            oneOf:\n              - type: boolean\n              - type: number\n          example: { qualified_lead: true, booked: true, conversion: false, revenue: 0 }\n        completed:\n          type: boolean\n          example: true\n        escalated:\n          type: boolean\n          example: false\n        escalationRule:\n          type: string\n          nullable: true\n          description: The declared rule that fired, when one did.\n          example: evidence.budget_band == needs_financing\n        modelCost:\n          type: integer\n          minimum: 0\n          description: |\n            Metered from real token usage, in minor units of `currency`. Zero when running\n            without a model credential, which is a fact rather than an estimate.\n          example: 214\n        currency:\n          type: string\n          pattern: \"^[A-Z]{3}$\"\n          example: INR\n        offline:\n          type: boolean\n          description: |\n            True when no model credential is configured; a deterministic keyword extractor\n            is answering and the conversation quality is not representative.\n          example: true\n      example:\n        leadId: web_3f9a21c07b4e6d15\n        journey: mba-admissions-qualification\n        version: 5\n        turns:\n          - { role: agent, text: \"Hi, I'm an AI assistant from the admissions team.\", at: \"2026-09-05T09:14:02.117Z\" }\n          - { role: lead, text: \"Executive MBA, this intake\", at: \"2026-09-05T09:14:31.004Z\" }\n        evidence:\n          - { field: target_program, required: true, value: executive_mba, confidence: 0.95, sensitive: false }\n          - { field: timeline, required: true, value: this_intake, confidence: 0.9, sensitive: false }\n          - { field: budget_band, required: true, value: null, confidence: null, sensitive: true }\n        missingRequired: [budget_band]\n        score: null\n        decision: null\n        metrics: { qualified_lead: false, booked: false, conversion: false, revenue: 0 }\n        completed: false\n        escalated: false\n        escalationRule: null\n        modelCost: 214\n        currency: INR\n        offline: false\n\n    ChatReply:\n      type: object\n      required: [reply, state]\n      additionalProperties: false\n      properties:\n        reply:\n          type: string\n          nullable: true\n          description: |\n            Null when the agent has nothing further to say — the conversation completed, or\n            a policy rule escalated it to a human.\n          example: Which programme are you considering?\n        state:\n          $ref: \"#/components/schemas/ChatState\"\n\n    LiveVersion:\n      type: object\n      required: [journey, version]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          example: 5\n        promotedAt:\n          type: string\n          format: date-time\n          description: Present on the response to a promotion.\n          example: \"2026-09-05T18:22:41.006Z\"\n      example:\n        journey: mba-admissions-qualification\n        version: 5\n\n    PromoteRequest:\n      type: object\n      required: [version]\n      additionalProperties: false\n      properties:\n        version:\n          type: integer\n          minimum: 1\n          description: A version that is already published.\n          example: 7\n      example:\n        version: 7\n\n    JourneySource:\n      type: object\n      required: [journey, version, yaml]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          example: 4\n        yaml:\n          type: string\n          example: \"journey: mba-admissions-qualification\\nversion: 4\\n...\"\n      example:\n        journey: mba-admissions-qualification\n        version: 4\n        yaml: \"journey: mba-admissions-qualification\\nversion: 4\\n...\"\n\n    DraftSpec:\n      type: object\n      required: [yaml]\n      additionalProperties: false\n      properties:\n        yaml:\n          type: string\n          description: The complete journey specification.\n          minLength: 1\n          maxLength: 40000\n          example: \"journey: mba-admissions-qualification\\nversion: 6\\n...\"\n      example:\n        yaml: \"journey: mba-admissions-qualification\\nversion: 6\\n...\"\n\n    DraftLintResult:\n      type: object\n      required: [valid, warnings]\n      additionalProperties: false\n      properties:\n        valid:\n          type: boolean\n          description: Whether the draft parses at all.\n          example: true\n        journey:\n          type: string\n          description: Present only when the draft parses.\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          description: Present only when the draft parses.\n          example: 6\n        error:\n          type: string\n          description: Present only when the draft does not parse.\n          maxLength: 500\n          example: routing needs exactly one \"otherwise\" rule, found 2\n        warnings:\n          type: array\n          items:\n            $ref: \"#/components/schemas/SpecWarning\"\n      example:\n        valid: true\n        journey: mba-admissions-qualification\n        version: 6\n        warnings: []\n\n    LintReport:\n      type: object\n      required: [journey, version, warnings]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          example: 4\n        warnings:\n          type: array\n          description: Empty when the version passes every check.\n          items:\n            $ref: \"#/components/schemas/SpecWarning\"\n      example:\n        journey: mba-admissions-qualification\n        version: 4\n        warnings:\n          - code: unreachable_qualification\n            message: required evidence can score at most 65, but qualifying needs 70. This journey cannot qualify anyone.\n\n    ReplayRequest:\n      type: object\n      required: [journey, a, b]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          minLength: 1\n          maxLength: 120\n          example: mba-admissions-qualification\n        a:\n          type: integer\n          minimum: 1\n          description: The baseline version.\n          example: 3\n        b:\n          type: integer\n          minimum: 1\n          description: The candidate version.\n          example: 4\n        n:\n          type: integer\n          minimum: 1\n          description: |\n            Cap the cohort to the first N leads. A cap is the difference between a screen\n            you can click and one that starts a six-figure token job.\n          example: 200\n        leadIds:\n          type: array\n          description: |\n            Which historical leads to replay. Omit to replay every lead on the journey.\n          items:\n            type: string\n            minLength: 1\n            maxLength: 64\n            example: L_meta_executive_528\n          example: [L_meta_executive_528, L_meta_executive_696]\n      example:\n        journey: mba-admissions-qualification\n        a: 3\n        b: 4\n\n    ReplayEstimate:\n      type: object\n      required: [available, leads, extracted, reused, estimatedUsd, modelled]\n      additionalProperties: false\n      properties:\n        available:\n          type: integer\n          minimum: 0\n          description: Leads on this journey in total.\n          example: 2000\n        leads:\n          type: integer\n          minimum: 0\n          description: Leads this replay would cover, after any cap.\n          example: 200\n        extracted:\n          type: integer\n          minimum: 0\n          description: Of those, how many need a model call. The only ones that cost.\n          example: 74\n        reused:\n          type: integer\n          minimum: 0\n          description: How many already carry their evidence on the record.\n          example: 126\n        estimatedUsd:\n          type: number\n          format: double\n          minimum: 0\n          description: From a measured per-extraction cost, not a guess.\n          example: 0.185\n        modelled:\n          type: boolean\n          description: |\n            False when no credential is configured, in which case the deterministic\n            extractor runs and the replay is free.\n          example: true\n      example:\n        available: 2000\n        leads: 200\n        extracted: 74\n        reused: 126\n        estimatedUsd: 0.185\n        modelled: true\n\n    ReplayCost:\n      type: object\n      description: |\n        What a replay actually cost. Replay writes no events — it is a read over history —\n        so its spend appears in no `CostObserved` row and would otherwise be invisible.\n      required: [leads, extracted, reused, usd]\n      additionalProperties: false\n      properties:\n        leads: { type: integer, minimum: 0, example: 200 }\n        extracted: { type: integer, minimum: 0, example: 74 }\n        reused: { type: integer, minimum: 0, example: 126 }\n        usd: { type: number, format: double, minimum: 0, example: 0.1832 }\n      example:\n        leads: 200\n        extracted: 74\n        reused: 126\n        usd: 0.1832\n\n    ReplayArm:\n      type: object\n      description: One version's result over the replayed cohort.\n      required: [version, qualifiedRate, projectedConversions]\n      additionalProperties: false\n      properties:\n        version:\n          type: integer\n          minimum: 1\n          example: 4\n        qualifiedRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          description: Share of the cohort this version would have qualified.\n          example: 0.048\n        projectedConversions:\n          type: number\n          format: double\n          minimum: 0\n          description: |\n            MODELLED. Observed conversion rates per routing decision, applied to this\n            version's counterfactual routing. An estimate, never an observation.\n          example: 89.5\n      example:\n        version: 4\n        qualifiedRate: 0.048\n        projectedConversions: 89.5\n\n    ReplayOutcome:\n      type: object\n      description: What one version did with one lead.\n      required: [leadId, decision, qualified, turns]\n      additionalProperties: false\n      properties:\n        leadId:\n          type: string\n          minLength: 1\n          maxLength: 64\n          example: L_meta_executive_696\n        decision:\n          type: string\n          description: The routing decision, named by the journey's own routing block.\n          example: hot\n        qualified:\n          type: boolean\n          example: true\n        turns:\n          type: integer\n          minimum: 0\n          example: 6\n      example:\n        leadId: L_meta_executive_696\n        decision: hot\n        qualified: true\n        turns: 6\n\n    Divergence:\n      type: object\n      description: |\n        A lead the two versions treated differently. This list is the answer to\n        \"show me where the new version actually changed something\".\n      required: [leadId, a, b, actualOutcome]\n      additionalProperties: false\n      properties:\n        leadId:\n          type: string\n          minLength: 1\n          maxLength: 64\n          example: L_meta_executive_696\n        a:\n          $ref: \"#/components/schemas/ReplayOutcome\"\n        b:\n          $ref: \"#/components/schemas/ReplayOutcome\"\n        actualOutcome:\n          type: string\n          nullable: true\n          description: OBSERVED. What really happened to this lead, or null if nothing did.\n          example: paid\n      example:\n        leadId: L_meta_executive_696\n        a: { leadId: L_meta_executive_696, decision: warm, qualified: false, turns: 6 }\n        b: { leadId: L_meta_executive_696, decision: hot, qualified: true, turns: 6 }\n        actualOutcome: paid\n\n    Lift:\n      type: object\n      required:\n        [n, a, b, absoluteLift, ci95, observedConversionByDecision, divergent, cost]\n      additionalProperties: false\n      properties:\n        n:\n          type: integer\n          minimum: 0\n          description: Leads replayed.\n          example: 2000\n        a:\n          $ref: \"#/components/schemas/ReplayArm\"\n        b:\n          $ref: \"#/components/schemas/ReplayArm\"\n        absoluteLift:\n          type: number\n          format: double\n          description: b's qualification rate minus a's, in percentage points as a fraction.\n          example: 0.029\n        ci95:\n          $ref: \"#/components/schemas/ConfidenceInterval\"\n        observedConversionByDecision:\n          type: object\n          description: |\n            OBSERVED. Historical conversion rate for each routing decision, measured from\n            what really happened. This is the factual half of the response.\n          additionalProperties:\n            type: number\n            format: double\n            minimum: 0\n            maximum: 1\n          example: { hot: 0.361, warm: 0.138, cold: 0.008, escalated: 0.002 }\n        divergent:\n          type: array\n          items:\n            $ref: \"#/components/schemas/Divergence\"\n        cost:\n          $ref: \"#/components/schemas/ReplayCost\"\n      example:\n        n: 2000\n        a: { version: 3, qualifiedRate: 0.018, projectedConversions: 66.1 }\n        b: { version: 4, qualifiedRate: 0.048, projectedConversions: 89.5 }\n        absoluteLift: 0.029\n        ci95: [0.023, 0.038]\n        observedConversionByDecision: { hot: 0.361, warm: 0.138, cold: 0.008 }\n        divergent: []\n        cost: { leads: 200, extracted: 74, reused: 126, usd: 0.1832 }\n\n    ConfidenceInterval:\n      type: array\n      description: |\n        A 95% interval as `[low, high]`. Always reported. A point estimate with no\n        interval invites exactly the challenge it cannot survive.\n      minItems: 2\n      maxItems: 2\n      items:\n        type: number\n        format: double\n      example: [0.023, 0.038]\n\n    Limits:\n      type: object\n      required: [maxCohort, offline]\n      additionalProperties: false\n      properties:\n        maxCohort:\n          type: integer\n          minimum: 1\n          description: Largest simulated or compared cohort this deployment will run.\n          example: 60\n        offline:\n          type: boolean\n          description: |\n            True when no model credential is configured, so nothing here can spend.\n          example: false\n      example:\n        maxCohort: 60\n        offline: false\n\n    SimulateRequest:\n      type: object\n      required: [journey, version, n]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          minLength: 1\n          maxLength: 120\n          example: mba-admissions-qualification\n        version:\n          type: integer\n          minimum: 1\n          example: 4\n        n:\n          type: integer\n          minimum: 1\n          maximum: 2000\n          description: |\n            Personas to run. Capped so that one request cannot start a five-figure model\n            bill.\n          example: 500\n        seed:\n          type: integer\n          minimum: 0\n          description: |\n            Persona generation seed. The same seed produces the same cohort, so a result\n            on stage is the result from rehearsal.\n          default: 1\n          example: 1\n      example:\n        journey: mba-admissions-qualification\n        version: 4\n        n: 500\n\n    CompareRequest:\n      type: object\n      required: [journey, a, b, n]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          minLength: 1\n          maxLength: 120\n          example: mba-admissions-qualification\n        a:\n          type: integer\n          minimum: 1\n          example: 4\n        b:\n          type: integer\n          minimum: 1\n          example: 5\n        n:\n          type: integer\n          minimum: 1\n          maximum: 2000\n          example: 200\n        seed:\n          type: integer\n          minimum: 0\n          description: Used for both arms, which is what makes the comparison paired.\n          default: 1\n          example: 1\n      example:\n        journey: mba-admissions-qualification\n        a: 4\n        b: 5\n        n: 200\n\n    LeadOutcome:\n      type: object\n      description: One simulated conversation's result.\n      required: [leadId, completed, qualified, escalated, turns]\n      additionalProperties: true\n      properties:\n        leadId:\n          type: string\n          minLength: 1\n          maxLength: 64\n          example: sim_0f31c7\n        completed:\n          type: boolean\n          description: Whether required evidence was collected and the lead was routed.\n          example: true\n        qualified:\n          type: boolean\n          example: false\n        escalated:\n          type: boolean\n          description: Whether a declared `escalate_when` rule fired.\n          example: false\n        turns:\n          type: integer\n          minimum: 0\n          example: 8\n      example:\n        leadId: sim_0f31c7\n        completed: true\n        qualified: false\n        escalated: false\n        turns: 8\n\n    RunSummary:\n      type: object\n      required:\n        [runId, journey, journeyVersion, n, completed, qualified, escalated, ghosted, avgTurns, results]\n      additionalProperties: false\n      properties:\n        runId:\n          type: string\n          description: |\n            Groups every event this run wrote. All of them are `sim`-scoped, so no\n            live-scoped read can see them.\n          minLength: 1\n          maxLength: 64\n          example: run_9c2f1a\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        journeyVersion:\n          type: integer\n          minimum: 1\n          example: 4\n        n:\n          type: integer\n          minimum: 0\n          example: 500\n        completed:\n          type: integer\n          minimum: 0\n          example: 412\n        qualified:\n          type: integer\n          minimum: 0\n          example: 118\n        escalated:\n          type: integer\n          minimum: 0\n          example: 34\n        ghosted:\n          type: integer\n          minimum: 0\n          description: Personas that stopped replying.\n          example: 54\n        avgTurns:\n          type: number\n          format: double\n          minimum: 0\n          example: 6.4\n        results:\n          type: array\n          items:\n            $ref: \"#/components/schemas/LeadOutcome\"\n      example:\n        runId: run_9c2f1a\n        journey: mba-admissions-qualification\n        journeyVersion: 4\n        n: 500\n        completed: 412\n        qualified: 118\n        escalated: 34\n        ghosted: 54\n        avgTurns: 6.4\n        results: []\n\n    RunQuality:\n      type: object\n      description: |\n        Aggregate scorecard over a run. Completeness and correctness are deterministic\n        checks against each persona's ground truth; the judge scores only what a regex\n        cannot.\n      required:\n        [n, meanCompleteness, meanCorrectness, violationRate, hallucinationRate, ghostRate, escalationRate, qualifiedRate, meanTurns]\n      additionalProperties: false\n      properties:\n        n:\n          type: integer\n          minimum: 0\n          example: 500\n        meanCompleteness:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          description: Share of required evidence fields actually collected.\n          example: 0.86\n        meanCorrectness:\n          type: number\n          format: double\n          nullable: true\n          minimum: 0\n          maximum: 1\n          description: |\n            Share of extracted values that matched the persona's ground truth. Null when\n            no persona carried ground truth to check against.\n          example: 0.94\n        violationRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          description: Share of conversations that breached a declared `never` rule.\n          example: 0.004\n        hallucinationRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          example: 0.01\n        ghostRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          example: 0.108\n        escalationRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          example: 0.068\n        qualifiedRate:\n          type: number\n          format: double\n          minimum: 0\n          maximum: 1\n          example: 0.236\n        meanTurns:\n          type: number\n          format: double\n          minimum: 0\n          example: 6.4\n      example:\n        n: 500\n        meanCompleteness: 0.86\n        meanCorrectness: 0.94\n        violationRate: 0.004\n        hallucinationRate: 0.01\n        ghostRate: 0.108\n        escalationRate: 0.068\n        qualifiedRate: 0.236\n        meanTurns: 6.4\n\n    Alert:\n      type: object\n      description: A declared threshold that a run crossed.\n      required: [id, severity, message, observed, threshold]\n      additionalProperties: false\n      properties:\n        id:\n          type: string\n          minLength: 1\n          maxLength: 60\n          example: policy_violations\n        severity:\n          type: string\n          enum: [warn, critical]\n          description: |\n            Policy breaches and evidence correctness are critical; ghosting is a warning,\n            because a lead who stops replying is often the lead's own choice whereas a\n            policy breach is always the agent's fault.\n          example: critical\n        message:\n          type: string\n          minLength: 1\n          maxLength: 300\n          example: 4.2% of conversations breached a \"never\" rule\n        observed:\n          type: number\n          format: double\n          example: 0.042\n        threshold:\n          type: number\n          format: double\n          example: 0.01\n      example:\n        id: policy_violations\n        severity: critical\n        message: 4.2% of conversations breached a \"never\" rule\n        observed: 0.042\n        threshold: 0.01\n\n    SimulationResult:\n      type: object\n      required: [summary, quality, alerts]\n      additionalProperties: false\n      properties:\n        summary:\n          $ref: \"#/components/schemas/RunSummary\"\n        quality:\n          $ref: \"#/components/schemas/RunQuality\"\n        alerts:\n          type: array\n          description: Empty when the run cleared every threshold.\n          items:\n            $ref: \"#/components/schemas/Alert\"\n      example:\n        summary:\n          runId: run_9c2f1a\n          journey: mba-admissions-qualification\n          journeyVersion: 4\n          n: 500\n          completed: 412\n          qualified: 118\n          escalated: 34\n          ghosted: 54\n          avgTurns: 6.4\n          results: []\n        quality:\n          n: 500\n          meanCompleteness: 0.86\n          meanCorrectness: 0.94\n          violationRate: 0.004\n          hallucinationRate: 0.01\n          ghostRate: 0.108\n          escalationRate: 0.068\n          qualifiedRate: 0.236\n          meanTurns: 6.4\n        alerts: []\n\n    ArmResult:\n      type: object\n      description: One side of an A/B comparison.\n      required: [target, summary, quality]\n      additionalProperties: false\n      properties:\n        target:\n          type: string\n          description: |\n            What this arm was pointed at. The same allocator that splits simulated cohorts\n            later points at a parallel-run cohort, so adoption needs no new machinery.\n          minLength: 1\n          maxLength: 120\n          example: v4\n        summary:\n          $ref: \"#/components/schemas/RunSummary\"\n        quality:\n          $ref: \"#/components/schemas/RunQuality\"\n\n    Scoreboard:\n      type: object\n      required:\n        [a, b, qualifiedDelta, qualifiedCi95, completenessDelta, correctnessDelta, verdict]\n      additionalProperties: false\n      properties:\n        a:\n          $ref: \"#/components/schemas/ArmResult\"\n        b:\n          $ref: \"#/components/schemas/ArmResult\"\n        qualifiedDelta:\n          type: number\n          format: double\n          description: b's qualification rate minus a's.\n          example: 0.031\n        qualifiedCi95:\n          $ref: \"#/components/schemas/ConfidenceInterval\"\n        completenessDelta:\n          type: number\n          format: double\n          example: 0.04\n        correctnessDelta:\n          type: number\n          format: double\n          nullable: true\n          example: 0.01\n        verdict:\n          type: string\n          enum: [b_better, a_better, inconclusive]\n          description: |\n            `inconclusive` whenever the interval spans zero. That is a result — the data\n            does not support a decision — not an error.\n          example: b_better\n\n    Totals:\n      type: object\n      description: |\n        Aggregate figures for one node of the attribution tree, or for the whole report.\n        Metric names come from the tenant's own `metrics:` block, so `counts` and `sums`\n        are keyed by names this platform did not choose.\n      required:\n        [leads, counts, sums, mediaCost, modelCost, totalCost, costPer, returnOnSpend]\n      additionalProperties: false\n      properties:\n        leads:\n          type: integer\n          minimum: 0\n          example: 2000\n        counts:\n          type: object\n          description: For each boolean metric, the number of leads it held for.\n          additionalProperties:\n            type: integer\n            minimum: 0\n          example: { qualified_lead: 80, booked: 80, conversion: 66 }\n        sums:\n          type: object\n          description: |\n            For each aggregate metric, its sum over leads. Monetary metrics are integer\n            minor units.\n          additionalProperties:\n            type: number\n          example: { revenue: 297000000 }\n        mediaCost:\n          type: integer\n          minimum: 0\n          description: MODELLED. Ad spend allocated to leads. Minor units.\n          example: 74900000\n        modelCost:\n          type: integer\n          minimum: 0\n          description: |\n            OBSERVED. Metered from real token usage and converted at write time with the\n            rate recorded in the event. Minor units.\n          example: 0\n        totalCost:\n          type: integer\n          minimum: 0\n          example: 74900000\n        costPer:\n          type: object\n          description: |\n            Total cost divided by the count of each boolean metric. **Null when the count\n            is zero** — an undefined ratio, not an infinite one.\n          additionalProperties:\n            type: number\n            nullable: true\n          example: { qualified_lead: 936250, conversion: 1134848 }\n        returnOnSpend:\n          type: object\n          description: |\n            Each aggregate metric divided by total cost. Null when nothing was spent.\n          additionalProperties:\n            type: number\n            nullable: true\n          example: { revenue: 39.7 }\n\n    AttributionNode:\n      type: object\n      description: |\n        One level of campaign to creative to journey version. A lead is attributed to the\n        version that produced its routing decision — the version that actually did the\n        work — falling back to the version it was ingested under.\n      required: [dimension, value, children, leads, counts, sums, mediaCost, modelCost, totalCost, costPer, returnOnSpend]\n      additionalProperties: false\n      allOf:\n        - $ref: \"#/components/schemas/Totals\"\n        - type: object\n          properties:\n            dimension:\n              type: string\n              enum: [campaign, creative, version]\n              example: campaign\n            value:\n              type: string\n              description: |\n                The campaign id, creative id, or version number as a string. Leads with no\n                campaign are grouped as `(unattributed)`.\n              minLength: 1\n              maxLength: 120\n              example: meta_scholarships\n            children:\n              type: array\n              description: The next level down. Empty at the version level.\n              items:\n                $ref: \"#/components/schemas/AttributionNode\"\n      example:\n        dimension: campaign\n        value: meta_scholarships\n        leads: 900\n        counts: { qualified_lead: 22, booked: 22, conversion: 20 }\n        sums: { revenue: 90000000 }\n        mediaCost: 13500000\n        modelCost: 0\n        totalCost: 13500000\n        costPer: { conversion: 675000 }\n        returnOnSpend: { revenue: 66.7 }\n        children:\n          - dimension: creative\n            value: cr_fees\n            leads: 450\n            counts: { qualified_lead: 13, booked: 13, conversion: 14 }\n            sums: { revenue: 63000000 }\n            mediaCost: 6750000\n            modelCost: 0\n            totalCost: 6750000\n            costPer: { conversion: 482142 }\n            returnOnSpend: { revenue: 93.3 }\n            children: []\n\n    AttributionReport:\n      type: object\n      required: [journey, currency, metricKinds, total, tree, caveats]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        currency:\n          type: string\n          pattern: \"^[A-Z]{3}$\"\n          example: INR\n        metricKinds:\n          type: object\n          description: |\n            Which declared metrics are counted and which are summed. The distinction is\n            load-bearing: a boolean metric aggregates as a count of leads, an aggregate\n            metric as a sum over them.\n          required: [booleans, aggregates]\n          additionalProperties: false\n          properties:\n            booleans:\n              type: array\n              items:\n                type: string\n                example: conversion\n              example: [qualified_lead, booked, conversion]\n            aggregates:\n              type: array\n              items:\n                type: string\n                example: revenue\n              example: [revenue]\n          example:\n            booleans: [qualified_lead, booked, conversion]\n            aggregates: [revenue]\n        total:\n          $ref: \"#/components/schemas/Totals\"\n        tree:\n          type: array\n          items:\n            $ref: \"#/components/schemas/AttributionNode\"\n        caveats:\n          type: array\n          description: |\n            Assumptions a customer is entitled to see beside the numbers — the allocation\n            method, leads with no campaign, leads with no spend ingested, and any metric\n            whose definition drifted between versions present in the data.\n          items:\n            type: string\n            example: Media spend is allocated evenly across the leads a campaign produced that day.\n          example:\n            - Media spend is allocated evenly across the leads a campaign produced that day. A weighted model is a customer decision, not a default.\n      example:\n        journey: mba-admissions-qualification\n        currency: INR\n        metricKinds:\n          booleans: [qualified_lead, booked, conversion]\n          aggregates: [revenue]\n        total:\n          leads: 2000\n          counts: { qualified_lead: 80, booked: 80, conversion: 66 }\n          sums: { revenue: 297000000 }\n          mediaCost: 74900000\n          modelCost: 0\n          totalCost: 74900000\n          costPer: { conversion: 1134848 }\n          returnOnSpend: { revenue: 39.7 }\n        tree: []\n        caveats:\n          - Media spend is allocated evenly across the leads a campaign produced that day.\n\n    Finding:\n      type: object\n      description: One thing worth telling a marketer, with the evidence for it attached.\n      required: [code, severity, claim, detail, n, effect, evidence]\n      additionalProperties: false\n      properties:\n        code:\n          type: string\n          enum:\n            [evidence_bottleneck, segment_divergence, drop_off, routing_miscalibration, timing, policy_friction, version_regression]\n          example: segment_divergence\n        severity:\n          type: string\n          enum: [high, medium, low]\n          example: medium\n        claim:\n          type: string\n          description: One sentence a marketer can read without translation.\n          minLength: 1\n          maxLength: 400\n          example: evidence.budget_band = needs_financing converts 8.6% worse than the rest of the cohort.\n        detail:\n          type: string\n          description: The numbers behind the claim.\n          minLength: 1\n          maxLength: 500\n          example: 0.2% vs 8.7% (n=509 / 743), 95% CI -10.6% .. -6.5%\n        n:\n          type: integer\n          minimum: 0\n          description: Support. A finding without it is an anecdote.\n          example: 1252\n        effect:\n          type: number\n          format: double\n          minimum: 0\n          description: Magnitude, used for ranking. Absolute difference in rates.\n          example: 0.086\n        ci95:\n          $ref: \"#/components/schemas/ConfidenceInterval\"\n        suggestion:\n          type: string\n          description: What to change in the spec, when there is a defensible answer.\n          maxLength: 400\n          example: Branch on evidence.budget_band = needs_financing rather than routing it on the shared score.\n        evidence:\n          type: object\n          description: Machine-readable backing for the claim, shaped per finding type.\n          additionalProperties: true\n          example:\n            dimension: evidence.budget_band\n            value: needs_financing\n            cohortRate: 0.002\n            baselineRate: 0.087\n            cohortSize: 509\n\n    InsightReport:\n      type: object\n      required: [journey, leadsAnalysed, findings, skipped]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        leadsAnalysed:\n          type: integer\n          minimum: 0\n          example: 2000\n        findings:\n          type: array\n          description: Ranked by severity, then by effect size.\n          items:\n            $ref: \"#/components/schemas/Finding\"\n        skipped:\n          type: array\n          description: |\n            Detectors that could not run, and why. Present so that silence is never\n            mistaken for a clean bill of health.\n          items:\n            type: object\n            required: [code, reason]\n            additionalProperties: false\n            properties:\n              code:\n                type: string\n                example: version_regression\n              reason:\n                type: string\n                minLength: 1\n                maxLength: 400\n                example: only one journey version in scope\n          example:\n            - code: version_regression\n              reason: only one journey version in scope\n      example:\n        journey: mba-admissions-qualification\n        leadsAnalysed: 2000\n        findings:\n          - code: segment_divergence\n            severity: medium\n            claim: evidence.budget_band = needs_financing converts 8.6% worse than the rest of the cohort.\n            detail: 0.2% vs 8.7% (n=509 / 743), 95% CI -10.6% .. -6.5%\n            n: 1252\n            effect: 0.086\n            ci95: [-0.106, -0.065]\n            suggestion: Branch on evidence.budget_band = needs_financing rather than routing it on the shared score.\n            evidence: { dimension: evidence.budget_band, value: needs_financing }\n        skipped:\n          - code: version_regression\n            reason: only one journey version in scope\n\n    CopilotRequest:\n      type: object\n      required: [journey, question]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          description: |\n            The journey in scope. Fixed by the caller, never chosen by the model — a\n            copilot that can retarget its own scope is a tenancy hole.\n          minLength: 1\n          maxLength: 120\n          example: mba-admissions-qualification\n        question:\n          type: string\n          minLength: 1\n          maxLength: 500\n          description: A question long enough to be an essay is a paste, not a question.\n          example: Why is my needs_financing cohort converting worse?\n      example:\n        journey: mba-admissions-qualification\n        question: Why is my needs_financing cohort converting worse?\n\n    ViewSeriesPoint:\n      type: object\n      required: [label, value]\n      additionalProperties: false\n      properties:\n        label:\n          type: string\n          minLength: 1\n          maxLength: 120\n          example: needs_financing (n=509)\n        value:\n          type: number\n          format: double\n          example: 0.2\n        band:\n          type: string\n          enum: [observed, modelled]\n          description: |\n            Drives the colouring that keeps measured and estimated numbers visually\n            distinct.\n          example: observed\n\n    View:\n      type: object\n      description: |\n        A rendering descriptor chosen from a closed set. The model never emits markup —\n        HTML from a model into the console DOM would be an XSS hole — so the console owns\n        how this looks and there is nothing here to sanitise.\n      required: [kind, title]\n      additionalProperties: false\n      properties:\n        kind:\n          type: string\n          enum: [bar, table, stat]\n          example: bar\n        title:\n          type: string\n          minLength: 1\n          maxLength: 160\n          example: Conversion by evidence.budget_band\n        unit:\n          type: string\n          maxLength: 12\n          description: Appended to each value. Bar views only.\n          example: \"%\"\n        series:\n          type: array\n          description: Bar views only.\n          items:\n            $ref: \"#/components/schemas/ViewSeriesPoint\"\n        columns:\n          type: array\n          description: Table views only.\n          items:\n            type: string\n            example: campaign\n          example: [campaign, leads, converted]\n        rows:\n          type: array\n          description: Table views only.\n          items:\n            type: array\n            items:\n              type: string\n              nullable: true\n          example: [[meta_scholarships, \"900\", \"20\"]]\n        value:\n          type: string\n          description: Stat views only.\n          maxLength: 60\n          example: \"₹11,348\"\n        caption:\n          type: string\n          description: Stat views only.\n          maxLength: 160\n          example: cost per enrolment\n      example:\n        kind: bar\n        title: Conversion by evidence.budget_band\n        unit: \"%\"\n        series:\n          - { label: \"needs_financing (n=509)\", value: 0.2, band: observed }\n          - { label: \"5L_to_15L (n=375)\", value: 9.1, band: observed }\n          - { label: \"above_15L (n=368)\", value: 8.4, band: observed }\n\n    SpecWarning:\n      type: object\n      description: |\n        A lint warning that travels with a proposal rather than being swallowed. A warning\n        hidden here is a warning nobody acts on.\n      required: [code, message]\n      additionalProperties: false\n      properties:\n        code:\n          type: string\n          enum:\n            [unreachable_qualification, unknown_scoring_field, unreachable_weight, unparseable_metric, unreachable_metric]\n          example: unreachable_qualification\n        message:\n          type: string\n          minLength: 1\n          maxLength: 500\n          example: required evidence can score at most 65, but qualifying needs 70.\n\n    ProposedDiff:\n      type: object\n      description: |\n        A proposed new journey version. Already parsed, linted and diffed before it\n        reached this response, so it would publish as it stands. Nothing has been\n        published.\n      required: [journey, fromVersion, toVersion, rationale, yaml, changes, warnings]\n      additionalProperties: false\n      properties:\n        journey:\n          type: string\n          example: mba-admissions-qualification\n        fromVersion:\n          type: integer\n          minimum: 1\n          example: 5\n        toVersion:\n          type: integer\n          minimum: 2\n          description: Always greater than `fromVersion`; a proposal must bump.\n          example: 6\n        rationale:\n          type: string\n          description: One sentence tying the change to the data that motivated it.\n          minLength: 1\n          maxLength: 400\n          example: budget_band = needs_financing converts 8.6% worse on the shared score; give it its own branch instead.\n        yaml:\n          type: string\n          description: The full proposed spec, ready to publish.\n          minLength: 1\n          example: \"journey: mba-admissions-qualification\\nversion: 6\\n...\"\n        changes:\n          type: array\n          items:\n            $ref: \"#/components/schemas/SpecChange\"\n        warnings:\n          type: array\n          items:\n            $ref: \"#/components/schemas/SpecWarning\"\n      example:\n        journey: mba-admissions-qualification\n        fromVersion: 5\n        toVersion: 6\n        rationale: budget_band = needs_financing converts 8.6% worse on the shared score; give it its own branch instead.\n        yaml: \"journey: mba-admissions-qualification\\nversion: 6\\n...\"\n        changes:\n          - path: routing.needs_financing_branch\n            kind: added\n            after:\n              when: evidence.budget_band == needs_financing\n              target: nurture.needs_financing_branch\n        warnings: []\n\n    CopilotAnswer:\n      type: object\n      required: [text, usedTools, offline]\n      additionalProperties: false\n      properties:\n        text:\n          type: string\n          minLength: 1\n          maxLength: 2000\n          example: evidence.budget_band = needs_financing converts 8.6% worse than the rest of the cohort.\n        view:\n          $ref: \"#/components/schemas/View\"\n        diff:\n          $ref: \"#/components/schemas/ProposedDiff\"\n        usedTools:\n          type: array\n          description: |\n            Which read models backed the answer. The audit trail for every number in it.\n          items:\n            type: string\n            enum: [roi, insights, cohort, read_spec, propose_diff]\n            example: insights\n          example: [insights, cohort, read_spec, propose_diff]\n        offline:\n          type: boolean\n          description: |\n            True when no model credential was configured and the answer came from keyword\n            routing over the same tools. The data is real either way; the reasoning is not.\n          example: true\n";
